        V("buhat-sa-l26", "búhat sa", "from (also for a hometown, and for time)", say="BU-hat sa", pos="phrase", group="from"),
        V("hanggang-l26", "hanggáng", "until", say="hang-GANG", pos="other", group="from"),
        V("noon-l26", "noón", "then (literally)", say="no-ON", pos="other", group="from"),
